(() => { const a = window.__CITY_APP, C = window.CITY, cm = a.controllerManager, y = C.SUBWAY_VIADUCTS[0].deck; a.cameraSystem.cinema = null; a.selectMode('person'); a.selectCamera('chase', true);
 let best = null; for (const r of C.DECK_RUNS) { if (!/^Bloor Street/.test(r.name)) continue; for (let i = 0; i + 1 < r.pts.length; i++) { const p = r.pts[i], q = r.pts[i + 1], d = Math.hypot((p.x + q.x) / 2 - 2240, (p.z + q.z) / 2 + 2800); if (!best || d < best.d) best = { d, p, q }; } }
 const { p, q } = best, L = Math.hypot(q.x - p.x, q.z - p.z); let ux = (q.x - p.x) / L, uz = (q.z - p.z) / L; if (ux < 0) { ux = -ux; uz = -uz; }
 const t = (2240 - p.x) * ux + (-2800 - p.z) * uz, cx = p.x + ux * t, cz = p.z + uz * t;
 a.teleportTo(cx - ux * 70 - uz * 3, cz - uz * 70 + ux * 3, Math.atan2(ux, uz), y); return { start: [+(cx - ux * 70).toFixed(1), +(cz - uz * 70).toFixed(1)], heading: +Math.atan2(ux, uz).toFixed(3), deck: y, run: best.p && best.d }; })()

